"""Writes the session bus's icon (an HVIF vector_icon) into
src/servers/dbus/SessionBusIcon.rdef:

    3rdparty/ce/tools/make_session_bus_icon.py > \\
        src/servers/dbus/SessionBusIcon.rdef
    3rdparty/ce/tools/make_session_bus_icon.py --preview icon.png

It shows on the notifications Linux and ported programs send through
the bus. The picture: a Renga-green bar (the bus) in Haiku's
three-quarter style, with three program tiles hanging from it, the
middle one an orange notification bubble. No mascot or trademark.
"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif

GREEN = ((126, 190, 74, 255), (78, 140, 46, 255))
ORANGE = ((240, 128, 40, 255), (196, 84, 22, 255))
GOLD = ((246, 196, 64, 255), (206, 150, 30, 255))
TILE = ((236, 232, 220, 255), (164, 160, 148, 255))
OUTLINE = (30, 32, 26, 255)


def skew(points):
	return [(x + (40 - y) * 0.12, y) for x, y in points]


def rounded_rect(x0, y0, x1, y1, r):
	points = []
	points += hvif.arc_points(x1 - r, y0 + r, r, -90, 0, 4)
	points += hvif.arc_points(x1 - r, y1 - r, r, 0, 90, 4)
	points += hvif.arc_points(x0 + r, y1 - r, r, 90, 180, 4)
	points += hvif.arc_points(x0 + r, y0 + r, r, 180, 270, 4)
	return points


def build():
	icon = hvif.Icon()
	# the bus
	icon.polygon(skew(rounded_rect(4, 10, 60, 20, 4)), hvif.gradient(
		(4, 10), (60, 20), [(0, GREEN[0]), (255, GREEN[1])]),
		outline=(OUTLINE, 3))
	# links down to the tiles
	for x in (14, 32, 50):
		icon.polygon(skew([(x - 2, 20), (x + 2, 20), (x + 2, 30),
			(x - 2, 30)]), hvif.gradient((x - 2, 20), (x + 2, 30),
			[(0, GOLD[0]), (255, GOLD[1])]))
	# two program tiles and a notification bubble between them
	for x0 in (5, 41):
		icon.polygon(skew(rounded_rect(x0, 30, x0 + 18, 50, 3)),
			hvif.gradient((x0, 30), (x0 + 18, 50),
			[(0, TILE[0]), (255, TILE[1])]), outline=(OUTLINE, 2))
	r = 4
	bubble = hvif.arc_points(42 - r, 30 + r, r, -90, 0, 4)
	bubble += hvif.arc_points(42 - r, 46 - r, r, 0, 90, 4)
	bubble += [(35, 46), (27, 55), (29, 46)]		# the tail
	bubble += hvif.arc_points(22 + r, 46 - r, r, 90, 180, 4)
	bubble += hvif.arc_points(22 + r, 30 + r, r, 180, 270, 4)
	icon.polygon(skew(bubble), hvif.gradient((22, 30), (42, 56),
		[(0, ORANGE[0]), (255, ORANGE[1])]), outline=(OUTLINE, 2))
	return icon


def rdef():
	data = build().flat()
	hexdata = data.hex().upper()
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * The session bus's icon. Generated by",
		" * 3rdparty/ce/tools/make_session_bus_icon.py; see there.",
		" */", "", "resource vector_icon {"]
	for i in range(0, len(hexdata), 64):
		lines.append("\t$\"%s\"" % hexdata[i:i + 64])
	lines.append("};")
	return "\n".join(lines) + "\n"


if __name__ == "__main__":
	if len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		icon = build()
		sheet = Image.new("RGBA", (16 + 32 + 64 + 128 + 40, 140),
			(216, 216, 216, 255))
		x = 8
		for size in (16, 32, 64, 128):
			sheet.paste(icon.preview(size, (216, 216, 216, 255)), (x, 4))
			x += size + 8
		sheet.save(sys.argv[2])
	else:
		print(rdef(), end="")
